    "quebec_vocab_0_english": "Québec French ના unique daily words — Montreal blend-in!",
    "quebec_vocab_1_english": "Daily Québec conversation expressions.",
    "quebec_vocab_2_english": "European French થી Quebec ઉચ્ચારણ ઘણો અલગ છે.",
