    "cod_coi_subtitle": "Direct & Indirect Object Pronouns",
    "pronominal_subtitle": "Conjugations for Daily Routine & More",
    "passe_recent_subtitle": "venir de + infinitif — હમણાં જ કંઈક કર્યું",
    "passe_recent_0_english": "Passé récent એવી action વર્ણવે જે હમણાં જ થઈ — 'હમણાં જ કંઈક કર્યું'. 'venir' ને present tense માં conjugate કરો, 'de/d'' ઉમેરો, પછી action નું infinitive.",
    "passe_recent_1_english": "Passé récent action પછીની ક્ષણ પર focus કરે — passé composé કરતાં વધુ નજીક. એ 'તમે હમણાં જ શું કર્યું?' નો જવાબ આપે.",
    "passe_recent_2_english": "આ time markers કયો tense વાપરવો એ સંકેત આપે — recent past, ચાલુ present, અથવા future. એમને ઓળખવાથી તરત સાચો tense પસંદ કરી શકાય.",
    "passe_recent_3_english": "બંને ભૂતકાળની વાત કરે, પણ passé récent નો અર્થ એ હમણાં જ થયું (સેકંડ/મિનિટ પહેલા), જ્યારે passé composé કોઈ પણ પૂરી થયેલી ભૂતકાળની action ને આવરી લે, નજીક હોય કે દૂર.",
    "passe_recent_4_english": "ફક્ત 'venir' (conjugated verb) ને ne…pas વડે wrap કરો. 'de + infinitive' negation ની બહાર, 'pas' પછી તરત જ રહે.",
    "pronominal_0_english": "Pronominal verb ને negative બનાવવા, reflexive pronoun ની પહેલાં ne અને conjugated verb પછી pas મૂકો. Reflexive pronoun હંમેશા તેના verb ની તરત પહેલાં રહે છે — તે ક્યારેય તેનાથી અલગ થતો નથી. Passé composé માં, ne pronoun ની પહેલાં અને pas auxiliary પછી આવે છે.",
