    "verbs_2_english": "-re हटाएं, endings जोड़ें। il/elle/on को कोई ending नहीं। उदाहरण: attendre (इंतज़ार करना)",
    "verbs_3_english": "Negative: verb को 'ne' + 'pas' से wrap करें। Vowel से पहले 'ne' → 'n''।",
