    "adjectives_subtitle": "Agreement in Gender & Number",
    "adjectives_0_english": "अंग्रेज़ी adjective के विपरीत, फ्रेंच adjective noun के gender-number के साथ match होता है।",
    "adjectives_1_english": "Negative sentences में adjective agreement कभी नहीं बदलती — सिर्फ article (un/une → de) बदलता है।",
