    "passe_compose_subtitle": "Talking About the Past",
    "passe_compose_0_english": "A1–B1 की main past tense। अधिकतर verbs 'avoir', key group 'être' use करते हैं।",
    "passe_compose_1_english": "सबसे common verbs के irregular past participles — याद करें!",
    "passe_compose_2_english": "6 common switch verbs: अगर कर्ता (subject) खुद हिल रहा है तो être का प्रयोग करें; अगर कर्ता किसी दूसरी चीज़ को हिला रहा है (COD है) तो avoir का प्रयोग करें!",
    "passe_compose_3_english": "Movement verbs être use करते हैं। Past participle subject के साथ agree करे!",
    "passe_compose_4_english": "Negative: ne…pas auxiliary verb के चारों ओर, past participle के नहीं।",
    "object_pronouns_subtitle": "Direct, Indirect & Stress Pronouns",
    "object_pronouns_0_english": "Direct object pronouns verb की action receive करते हैं। फ्रेंच: verb से पहले।",
