    "object_pronouns_3_english": "Preposition के बाद, emphasis, या verb-less answers: stress pronouns।",
    "imperatives_subtitle": "Commands, Ability, Obligation & Wishes",
    "imperatives_0_english": "Commands: सिर्फ 3 forms — tu, nous, vous। Subject pronoun drop!",
    "imperatives_1_english": "Negative command: verb को ne…pas से wrap।",
