    "imperatives_3_english": "Modal verbs meaning पूरा करने के लिए infinitive के साथ।",
    "imperatives_4_english": "Negative: modal verb को ne…pas wrap — infinitive unchanged।",
    "useful_structures_subtitle": "Near Future, C'est, Il y a & More",
    "useful_structures_0_english": "Future plans — 'going to do something' — सबसे आसान तरीका।",
    "useful_structures_1_english": "Negative: aller verb wrap + c'est/il y a structures।",
