    "useful_structures_3_english": "'Avoir' — अंग्रेज़ी 'to be' की जगह physical states के लिए।",
    "quebec_vocab_subtitle": "Expressions, Vocabulary & Pronunciation",
    "quebec_vocab_0_english": "Québec French के unique daily words।",
    "quebec_vocab_1_english": "Daily Québec conversation expressions।",
    "quebec_vocab_2_english": "European French से Quebec उच्चारण बहुत अलग है।",
    "quebec_vocab_3_english": "Montreal में French learner के लिए practical survival phrases।",
    "cod_coi_subtitle": "Direct & Indirect Object Pronouns",
    "pronominal_subtitle": "Conjugations for Daily Routine & More",
    "verb_endings_subtitle": "Interactive Conjugation Workshop",
    "verb_endings_0_english": "हर regular French verb तीन में से एक group में होती है — -ER (सबसे common), -IR, या -RE। Infinitive ending देखें।",
    "verb_endings_0_tip": "💡 लगभग 90% French verbs -ER verbs हैं। अगर नई verb -er में खत्म हो तो आप इसे conjugate कर सकते हैं!",
    "verb_endings_1_english": "-er infinitive से -er हटाएं, फिर ये endings जोड़ें। je/il एक जैसे sound करते हैं, nous को -ons, vous को -ez, और ils -ent हमेशा silent।",
    "verb_endings_1_tip": "🍁 QC: 'ils parlent' और 'il parle' एक जैसे sound करते हैं। -ent ending 100% silent है!",
    "verb_endings_2_english": "-IR group में nous/vous/ils endings से पहले -iss- infix जुड़ता है। Singular endings -is/-it इस group के unique हैं।",
    "verb_endings_2_tip": "💡 nous/vous/ils में -iss- infix -IR verbs की पहचान है: finissons, choisissons, réussissons।",
    "verb_endings_3_english": "-RE group सबसे tricky है: il/elle/on को कोई ending नहीं मिलती — सिर्फ stem रहता है। je/tu endings -s silent हैं।",
    "verb_endings_3_tip": "💡 il/elle पर zero-ending मुख्य अंतर है। 'il attend' — -re पूरी तरह हटती है और कुछ नहीं जुड़ता।",
    "verb_endings_4_english": "अधिकतर conjugation endings spoken French में silent होती हैं। यह समझना सबसे common pronunciation गलतियाँ रोकता है।",
    "verb_endings_4_tip": "🍁 QC insight: -ER verbs में je/tu/il/ils सभी एक जैसे sound करते हैं, इसलिए subject pronouns ज़रूरी हैं!",
    "passe_recent_subtitle": "venir de + infinitif — अभी-अभी कुछ किया",
    "passe_recent_0_english": "Passé récent उस action को बताता है जो अभी-अभी हुई — 'अभी-अभी कुछ किया'। 'venir' को present tense में conjugate करें, 'de/d'' जोड़ें, फिर action का infinitive।",
    "passe_recent_1_english": "Passé récent action के तुरंत बाद के पल पर focus करता है — passé composé से ज़्यादा नज़दीक। यह 'तुमने अभी-अभी क्या किया?' का जवाब देता है।",
    "passe_recent_2_english": "ये time markers बताते हैं कि कौन-सा tense इस्तेमाल करें — recent past, चालू present, या future। इन्हें पहचानने से तुरंत सही tense चुन सकते हैं।",
    "passe_recent_3_english": "दोनों भूतकाल की बात करते हैं, पर passé récent का मतलब है अभी-अभी हुआ (सेकंड/मिनट पहले), जबकि passé composé किसी भी पूरी हुई भूतकाल की action को कवर करता है, नज़दीक हो या दूर।",
    "passe_recent_4_english": "सिर्फ़ 'venir' (conjugated verb) को ne…pas से wrap करें। 'de + infinitive' negation के बाहर, 'pas' के तुरंत बाद रहता है।",
    "pronominal_0_english": "Pronominal क्रिया को नकारात्मक बनाने के लिए, reflexive pronoun से पहले ne और conjugated क्रिया के बाद pas लगाएं। Reflexive pronoun हमेशा अपनी क्रिया के ठीक पहले रहता है — यह उससे कभी अलग नहीं होता। Passé composé में, ne सर्वनाम से पहले और pas auxiliary के बाद आता है।",
