    window.sectionTranslations = sectionTranslations;

    function t(key) {
      const cur = window.currentLang || currentLang;
      const lang = translations[cur] || translations.en;
      return (lang.ui && lang.ui[key]) || (translations.en.ui && translations.en.ui[key]) || key;
    }
    window.t = t;

    /**
     * Allows dynamically registering or extending translations for any new section added.
     * @param {string} sectionId - The ID of the section (e.g. 'subjonctif')
     * @param {Object} data - An object keyed by language code: { en: {...}, fa: {...}, gu: {...}, hi: {...}, ta: {...}, ko: {...}, zh: {...} }
     */
    function registerSectionTranslations(sectionId, data) {
      if (!sectionId || !data) return;
      for (const [lang, translationsObj] of Object.entries(data)) {
        if (!sectionTranslations[lang]) sectionTranslations[lang] = {};
        for (const [key, val] of Object.entries(translationsObj)) {
          // If key is already prefixed with sectionId, keep as is; otherwise prefix it
          const fullKey = key.startsWith(sectionId + '_') ? key : (sectionId + '_' + key);
          sectionTranslations[lang][fullKey] = val;
        }
      }
    }
    window.registerSectionTranslations = registerSectionTranslations;

    function tSectionTitle(sectionId) {
      const cur = window.currentLang || currentLang;
      if (cur === 'en') return null;
      const st = sectionTranslations[cur];
      if (!st) return null;
      return st[sectionId + '_title'] || null;
    }
    window.tSectionTitle = tSectionTitle;

    function tSection(sectionId, blockIndex, field) {
      const cur = window.currentLang || currentLang;
      if (cur === 'en') return null; // use original data
      const st = sectionTranslations[cur];
      if (!st) return null;
      const k = sectionId + '_' + blockIndex + '_' + field;
      return st[k] || null;
    }
    window.tSection = tSection;

    function tSectionSubtitle(sectionId) {
      const cur = window.currentLang || currentLang;
      if (cur === 'en') return null;
      const st = sectionTranslations[cur];
      if (!st) return null;
      return st[sectionId + '_subtitle'] || null;
    }
    window.tSectionSubtitle = tSectionSubtitle;

    function updateAppSubtitle() {
      const el = document.getElementById('app-subtitle');
      if (el) el.textContent = t('appSubtitle');
      updateDomTranslations();
    }
    window.updateAppSubtitle = updateAppSubtitle;

    function updateDomTranslations() {
      if (typeof document === 'undefined') return;
      document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (!key) return;
        const translated = t(key);
        if (translated && translated !== key) {
          el.textContent = translated;
        }
      });
    }
    window.updateDomTranslations = updateDomTranslations;

    // Register section translations for Personality Adjectives
